// =============================================================================
// Node: Map Enums → Labels
// Tujuan: Convert raw enum IDs dari Bitrix ke label readable + ambil RFP
//         yang sudah di-filter via AI di node sebelumnya.
// Output: Object yang siap dipakai di "Build Prompt (EDIT ME)" sebagai {{ $json.* }}
// =============================================================================
//
// CARA TAMBAH FIELD BARU (step-by-step untuk Michael / Admin):
//
//   1. Di Bitrix24: buat custom field baru di SPA "Proposal Estimation" (entityTypeId=2098)
//      via menu Settings → Custom Fields.
//
//   2. Verify field code & enum IDs (kalau field-nya tipe enumeration) lewat call:
//        POST /rest/<user>/<token>/crm.item.fields
//        Body: {"entityTypeId": 2098}
//      Atau lihat docs/BITRIX_SCHEMA_REFERENCE.md di repo.
//
//   3. KALAU FIELD TIPE ENUMERATION:
//      a. Tambah const MAP_<NAMA> di bawah (section STEP 2):
//         const MAP_INDUSTRY = { '9201': 'Finance', '9203': 'Retail', '9205': 'Healthcare' };
//      b. Tambah di return object (section STEP 5):
//         industry: lookup(MAP_INDUSTRY, item.ufCrm497Industry),
//
//   4. KALAU FIELD TIPE STRING / NUMBER:
//      Langsung tambah di return object:
//        industry: item.ufCrm497Industry || '(empty)',
//
//   5. Buka node "Build Prompt (EDIT ME)" → tambah baris baru:
//      Industry: {{ $json.industry }}
//
//   6. Save workflow (Ctrl+S), test dengan kirim webhook.
//
// =============================================================================

// === STEP 1: AMBIL DATA SUMBER ===
//
// 'item'     = data lengkap SPA item dari Bitrix (hasil crm.item.get di node
//              "Bitrix: Get SPA Item"). Referensi langsung supaya tidak bergantung
//              pada Combine nodes.
//
// 'rfp_text' = hasil ekstraksi AI dari PDF RFP (di node "Call OpenAI - Extract
//              RFP Sections"). Sudah di-FILTER hanya berisi: functional req,
//              integrations, workflows, reporting needs, mobile/web requirements.
//              Legal, SLA, company profile, commercial terms sudah dibuang.

const item = $('Bitrix: Get SPA Item').item.json.result.item;
const rfp_text = $input.item.json.choices?.[0]?.message?.content ?? '';

// === STEP 2: ENUM MAPPINGS ===
//
// Mapping dari enum ID (string angka) ke label readable.
// Sumber otoritatif: docs/BITRIX_SCHEMA_REFERENCE.md di repo.
//
// FORMAT: const MAP_<NAMA_FIELD> = { 'enum_id_1': 'Label 1', 'enum_id_2': 'Label 2', ... }

const MAP_PLATFORM = {
  '9011': 'Web',
  '9013': 'Mobile',
  '9015': 'Portal',
  '9017': 'API'
};

const MAP_INTEGRATE = {
  '9019': 'Yes',
  '9021': 'No'
};

const MAP_COMPLEXITY = {
  '9023': 'Low',
  '9025': 'Medium',
  '9027': 'High'
};

const MAP_TIMELINE = {
  '9029': 'Normal',
  '9031': 'Dipercepat'
};

// === STEP 3: HELPER FUNCTION ===
//
// Safely lookup label by enum ID. Return '(unknown: <id>)' kalau ID tidak dikenal.
const lookup = (map, val) => map[String(val)] ?? `(unknown: ${val})`;

// === STEP 4: HANDLE FIELD MULTI-SELECT ===
//
// Platform di Bitrix multi-select → return-nya array of IDs (mis: ["9011","9015"]).
// Kalau cuma 1 dipilih → kadang return single value (bukan array).
// Code di bawah handle kedua kasus secara safe.
const platformIds = Array.isArray(item.ufCrm497Platform)
  ? item.ufCrm497Platform
  : (item.ufCrm497Platform ? [item.ufCrm497Platform] : []);

const platformLabels = platformIds
  .map(id => lookup(MAP_PLATFORM, id))
  .join(', ') || '(not specified)';

// === STEP 5: RETURN OUTPUT ===
//
// Object yang di-return di sini jadi $json di node berikutnya ("Build Prompt").
// Setiap key bisa di-reference di prompt template sebagai {{ $json.<key> }}.
return {
  json: {
    // --- ID & metadata ---
    item_id: item.id,
    title: item.title || '(no title)',
    stage_id: item.stageId,

    // --- Free-text fields (langsung passthrough) ---
    summary: item.ufCrm497Summary || '(empty)',
    feature_list: item.ufCrm497FeatureList || '(empty)',
    integration_detail: item.ufCrm497IntegrationDetail || '(empty)',

    // --- Enum fields (converted ke label readable) ---
    platform_labels: platformLabels,
    is_integrate: lookup(MAP_INTEGRATE, item.ufCrm497IsIntegrate),
    complexity: lookup(MAP_COMPLEXITY, item.ufCrm497Complexity),
    timeline: lookup(MAP_TIMELINE, item.ufCrm497Timeline),

    // --- Number fields ---
    user_scale: item.ufCrm497UserScale ?? 0,

    // --- RFP (sudah di-filter AI: hanya functional req, integrations, workflows,
    //     reporting needs, mobile/web requirements) ---
    rfp_text: rfp_text || '(tidak ada file RFP atau extraction kosong)'
  }
};

